52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private final ClinicService clinicService;
58	
59	    private final OwnerMapper ownerMapper;
60	
61	    private final PetMapper petMapper;
62	
63	    private final VisitMapper visitMapper;
64	
65	    public OwnerRestControllerV1(ClinicService clinicService,
66	                                 OwnerMapper ownerMapper,
67	                                 PetMapper petMapper,
68	                                 VisitMapper visitMapper) {
69	        this.clinicService = clinicService;
70	        this.ownerMapper = ownerMapper;
71	        this.petMapper = petMapper;
72	        this.visitMapper = visitMapper;
73	    }
74	
75	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
76	    @Override
77	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
78	        Collection<Owner> owners;
79	        if (lastName != null) {
80	            owners = this.clinicService.findOwnerByLastName(lastName);
81	        } else {
82	            owners = this.clinicService.findAllOwners();
83	        }
84	        if (owners.isEmpty()) {
85	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
86	        }
87	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
93	        Owner owner = this.clinicService.findOwnerById(ownerId);
94	        if (owner == null) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
103	        HttpHeaders headers = new HttpHeaders();
104	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
105	        if (owner.getRegistrationDate() == null) {
106	            owner.setRegistrationDate(LocalDate.now());
107	        }
108	        if (this.clinicService.existsIdenticalOwner(owner)
109	            || this.clinicService.existsOwnerWithTelephone(owner.getTelephone())
110	            || this.clinicService.existsOwnerWithEmail(owner.getEmail())) {
111	            return new ResponseEntity<>(HttpStatus.CONFLICT);
112	        }
113	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
114	        this.clinicService.saveOwner(owner);
115	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
116	        headers.setLocation(UriComponentsBuilder.newInstance()
117	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
118	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
124	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
125	        if (currentOwner == null) {
126	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
127	        }
128	        currentOwner.setAddress(ownerFieldsDto.getAddress());
129	        currentOwner.setCity(ownerFieldsDto.getCity());
130	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
131	        currentOwner.setLastName(ownerFieldsDto.getLastName());
132	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
133	        this.clinicService.saveOwner(currentOwner);
134	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Transactional
139	    @Override
140	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
141	        Owner owner = this.clinicService.findOwnerById(ownerId);
142	        if (owner == null) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        this.clinicService.deleteOwner(owner);
146	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
